{
  "selections": [
    {
      "trait_id": "/intermediate_beliefs/rule",
      "background_ids": ["/childhood_data"],
      "relevance": "내담자가 '말하기 전에 이미 괜찮은 상태가 되어 있다'고 표현한 것, 7년 동안 '아니요'를 말해본 적이 없다는 것이 이 규칙의 직접적 표현. 상담사가 '단단한 규칙처럼 몸에 배어 있다'고 명명한 부분과 정확히 대응."
    },
    {
      "trait_id": "/intermediate_beliefs/attitude",
      "background_ids": ["/childhood_data"],
      "relevance": "내담자가 '아니요라고 말하는 순간, 뒤에 있는 사람들이 저를 아, 이 정도야? 하는 느낌. 실망스러운 사람'이라고 묘사한 것은 약점·부족한 모습이 드러나는 것을 끔찍하게 여기는 태도가 작동하는 장면. 어릴 때 힘들다는 말이 '듣기 싫은 거'였던 경험과 연결."
    },
    {
      "trait_id": "/core_belief/young_schema",
      "background_ids": ["/childhood_data"],
      "relevance": "'실망시키는 사람'이라는 이미지, '진짜 나'가 드러나면 안 된다는 느낌이 결함/수치심 도식의 핵심. 상담사가 '괜찮은 척 안에 완전히 있으면 이런 의심이 안 들어'라고 한 것은 이 도식이 작동 중임을 간접적으로 짚은 것."
    },
    {
      "trait_id": "/core_belief/core_belief_statement",
      "background_ids": ["/childhood_data"],
      "relevance": "'아니요라고 말하면 실망시키는 사람'이라는 공포는 '진짜 나를 알면 떠날 것이다'는 핵심 신념의 변형. 내담자가 '그다음은 말 안 해도 되죠?'라고 한 것은 그 신념의 결론(버림받음)을 말로 꺼내는 것이 두려운 것."
    },
    {
      "trait_id": "/intermediate_beliefs/assumption_negative",
      "background_ids": ["/childhood_data"],
      "relevance": "내담자가 '벅차다고 말하면 못 한다는 사람 되는 거잖아요'라고 한 것은 '부족한 모습을 보이면 실망해서 떠난다'는 가정의 직접적 발화. 팀장님 앞에서 '네, 할게요'를 하는 순간이 이 가정이 작동하는 장면."
    },
    {
      "trait_id": "/coping_strategies/1",
      "background_ids": ["/situations/3"],
      "relevance": "내담자가 '그다음 날은 또 아무 일 없는 것처럼 출근하고'라고 한 것은 낮에 밝고 문제없는 모습을 유지하고 힘든 감정은 혼자 삭히는 대응 전략의 직접적 서술. 밤에 떠오르는 '괜찮은 척했던 순간'들이 낮의 전략과 밤의 붕괴를 함께 보여줌."
    }
  ]
}

